function Ghost() {
  // storing life amount
  this.life = 9;
  this.isDead = false;
  // creating a 'random' id
  this.id = (Math.random() * 100000).toString();
  this.sprite = Game.images['ghost'];
  this.oscillation = 0; // our ghost must fluctuate
  this.speed = 2;

  // width and height
  this.width = 708;
  this.height = 400;

  // starting position
  this.startpos = {
    x: Game.WIDTH,
    y: Game.ground_level - 350
  };

  // drawing ghost
  Game.c.drawImage(this.sprite, this.startpos.x, this.startpos.y, this.width, this.height);

}

Ghost.prototype.render = function() {
  if (this.life <= 0) {
    this.die();
    return;
  }
  // if this position is < 150, the game is Over

  if (this.startpos.x < 0) {
    if (!Game.over) Game.complete();
  }

  // this method is called by game render to render each ghost in the scene
  Game.c.drawImage(this.sprite, this.startpos.x, this.startpos.y + parseFloat(Math.sin(this.oscillation) * 2), this.width, this.height);
  // moving the ghost on the ground
  this.startpos.x -= this.speed;
  // oscillation
  this.oscillation += 0.1;
};

Ghost.prototype.die = function() {
  // removing this ghost from game
  delete Game.ghosts[this.id];

  // 50 pòints for every death
  Game.points += 50;
};

Ghost.prototype.hit = function(bullet) {
  this.life -= bullet.damage;
  if (this.life <= 0) {
    this.die();
    return;
  }
  // decreasing speed
  this.speed = 1;

  // 5 points for every hit
  Game.points += 5;
};

function Bullet() {
  // storing damage amount
  this.damage = 3;
  this.id = (Math.random() * 100000).toString();
  this.speed = 5;
  this.startpos = {
    x: 280,
    y: Game.ground_level - 50
  };

  this.radius = 10;

  Game.c.beginPath();
  Game.c.arc(this.startpos.x, this.startpos.y, this.radius, 0, 2 * Math.PI, false);
  Game.c.fillStyle = 'grey';
  Game.c.fill();
  Game.c.lineWidth = 2;
  Game.c.strokeStyle = '#000';
  Game.c.stroke();

  // 1 point added for each bullet
  Game.points += 1;
}

Bullet.prototype.render = function() {
  Game.c.beginPath();
  Game.c.arc(this.startpos.x, this.startpos.y, this.radius, 0, 2 * Math.PI, false);
  Game.c.fillStyle = 'grey';
  Game.c.fill();
  Game.c.lineWidth = 2;
  Game.c.strokeStyle = '#000';
  Game.c.stroke();

  // updating startpos
  this.startpos.x += this.speed;

  // if the bullet is outside the game scene
  if (this.startpos.x > Game.WIDTH) {
    this.remove();
    return;
  }

  for (var i in Game.ghosts) {
    if (this.startpos.x > Game.ghosts[i].startpos.x + 250) {
      // we hit a ghost
      Game.ghosts[i].hit(this);
      this.remove();
    }
  }
};

Bullet.prototype.remove = function() {
  // removing bullet from scene
  delete Game.bullets[this.id];
};

var Game = {
  sprites: {
    ghost: "data:image/png/;base64,",
    ground: "data:image/png/;base64,",
    moon: "data:image/png/;base64,",
    tree1: "data:image/png/;base64,",
    tree2: "data:image/png/;base64,",
    tree3: "data:image/png/;base64,",

    // player and ammunition boxes
    ammo1: "data:image/png/;base64,",
    bullet: "data:image/png/;base64,",
    cannon: "data:image/png/;base64,",
  },
  // GAME PROPERTIES
  ground_level: 400,
  sky_level: 200,
  numstars: 50,
  starpositions: [],
  ghosts: {}, // holding ghosts
  bullets: {},
  points: 0,
  keys: [],

  // reloading flag
  isreloading: false,
  bullet_count: 0,

  // reaction time
  reaction: 10,
  lastreaction: 0,

  // flag for game over
  over: false,

  // forbidden keys
  forbidden: [],

  _loadImages: function(sources, callback) {
    console.log(' inside load images');
    var images = {};
    var loadedImages = 0;
    var numImages = 0;
    // get num of sources
    for (var src in sources) {
      numImages++;
    }
    console.log(numImages);
    for (var src in sources) {
      images[src] = new Image();
      images[src].onload = function() {
        if (++loadedImages >= numImages) {
          callback(images);
        }
      };
      images[src].src = sources[src];
    }
  },

  hex2rgba: function(hex, opacity) {
    hex = hex.replace('#', '');
    r = parseInt(hex.substring(0, 2), 16);
    g = parseInt(hex.substring(2, 4), 16);
    b = parseInt(hex.substring(4, 6), 16);

    result = 'rgba(' + r + ',' + g + ',' + b + ',' + opacity / 100 + ')';
    return result;
  },

  randomInt: function(min, max) {
    return Math.floor(Math.random() * (max - min + 1) + min);
  },

  createForbidden: function() {
    Game.forbidden = [];
    // creating forbidden keys
    Game.keys = "abcdefghijklmnopqrstuvwxyz".split("");
    var numForbidden = (Math.random() * 5) + 5;
    while (Game.forbidden.length < numForbidden) {
      var index = parseInt(Math.random() * Game.keys.length);
      if (Game.forbidden.indexOf(Game.keys[index]) == -1) {
        Game.forbidden.push(Game.keys[index]);
      }
    }

  },

  // canvas properties
  canvas: undefined,
  context: undefined,
  gamecanvas: undefined,
  c: undefined,
  HEIGHT: 500,
  WIDTH: window.innerWidth,

  init: function() {
    Game.canvas = document.getElementById('canvas');
    Game.context = Game.canvas.getContext('2d');

    Game.gamecanvas = document.getElementById('gamecanvas');
    Game.c = Game.gamecanvas.getContext('2d');

    // setting height and width
    Game.canvas.height = Game.HEIGHT;
    Game.canvas.width = Game.WIDTH;

    Game.gamecanvas.height = Game.HEIGHT;
    Game.gamecanvas.width = Game.WIDTH;

    // loading images
    Game._loadImages(Game.sprites, function(images) {
      console.log(images);
      // now storing images
      Game.images = images;
      Game.drawBackground();
      // calling game render
      Game.render();
    });
  },

  complete: function() {
    // the game is over
    clearInterval(Game.ghostInterval);
    clearInterval(Game.speedInterval);
    clearInterval(Game.forbiddenInterval);
    clearInterval(Game.uiInterval);

    Game.cancelAnimationFrame(Game.animationId);

    Game.over = true;
    
    
    // display alert
    swal({title: "The game is over!", text:"Your score is " + (Game.points) + ". Please reload the page!", showConfirmButton: true, timer: 6000});
  },

  // render method
  render: function() {
    if (Game.over) return;

    Game.clear();

    // updating cloud and stars
    Game.renderSky();

    // updating bullets
    for (var j in Game.bullets) {
      Game.bullets[j].render();
    }

    // updating ghost positions
    for (var i in Game.ghosts) {
      Game.ghosts[i].render();
    }

    Game.animationId = Game.requestAnimationFrame(Game.render);
  },

  // firing bullet
  fireBullet: function() {
    var b = new Bullet();
    Game.bullets[b.id] = b;
  },

  // creating ghost
  createGhost: function() {
    // adding ghost to game
    var g = new Ghost();
    Game.ghosts[g.id] = g;
  },

  renderSky: function() {
    // clearing the sky except the moon
    Game.context.clearRect(300, 0, Game.WIDTH - 200, Game.sky_level);
    for (var i = 0; i < Game.numstars; i++) {
      Game.context.fillStyle = Game.hex2rgba('#d4d4d4', (Math.random() * 70) + 30);
      Game.context.fillRect(Game.starpositions[i].x, Game.starpositions[i].y, Game.randomInt(2, 3), Game.randomInt(2, 3));
    }
  },

  drawBackground: function() {
    // we don't need to clear everything
    // drawing ground
    Game.drawGround();
    // drawing the sky
    Game.drawSky();
  },

  drawGround: function() {
    var pattern = Game.context.createPattern(Game.images['ground'], "repeat");
    Game.context.rect(0, Game.ground_level, Game.WIDTH, Game.HEIGHT - Game.ground_level);
    Game.context.fillStyle = pattern;
    Game.context.fill();
    Game.context.fillStyle = Game.hex2rgba('#563D28', 50);
    Game.context.fillRect(0, Game.ground_level, Game.WIDTH, Game.HEIGHT - Game.ground_level);
    Game.context.fillStyle = 'rgba(40, 40, 40, 0.5)';
    Game.context.fillRect(0, Game.ground_level, Game.WIDTH, Game.HEIGHT - Game.ground_level);
    // drawing trees
    // trees
    Game.context.drawImage(Game.images['tree1'], 150, 200, 500, Game.ground_level - 200);
    Game.context.drawImage(Game.images['tree1'], 400, 200, 500, Game.ground_level - 200);
    Game.context.drawImage(Game.images['tree1'], 550, 200, 500, Game.ground_level - 200);
    Game.context.drawImage(Game.images['tree1'], 1300, 200, 500, Game.ground_level - 200);
    Game.context.drawImage(Game.images['tree2'], 900, 200, 500, Game.ground_level - 200);
    // bush
    Game.context.drawImage(Game.images['tree3'], 150, 300, 400, Game.ground_level - 300);
    Game.context.drawImage(Game.images['tree3'], 500, 300, 400, Game.ground_level - 300);
    Game.context.drawImage(Game.images['tree3'], 900, 300, 400, Game.ground_level - 300);
    Game.context.drawImage(Game.images['tree3'], 1200, 300, 400, Game.ground_level - 300);

    // adding cannon
    Game.context.drawImage(Game.images['cannon'], 100, 300, 300, 100);
    // adding boxes
    Game.context.drawImage(Game.images['ammo1'], -150, 210, 400, Game.ground_level - 200);
    // adding bullets
    Game.context.drawImage(Game.images['bullet'], 0, 300, 60, 30);
    Game.context.drawImage(Game.images['bullet'], 12, 300, 60, 30);
    Game.context.drawImage(Game.images['bullet'], 24, 300, 60, 30);
    Game.context.drawImage(Game.images['bullet'], 36, 300, 60, 30);
    Game.context.drawImage(Game.images['bullet'], 48, 300, 60, 30);
    Game.context.drawImage(Game.images['bullet'], 60, 300, 60, 30);

  },

  drawSky: function() {
    // drawing halo
    Game.context.beginPath();
    var grd = Game.context.createRadialGradient(125, 100, 1, 125, 100, 150);
    grd.addColorStop(0, 'rgb(100, 100, 100)');
    grd.addColorStop(1, 'rgb(40, 40, 40)');
    Game.context.arc(125, 100, 150, 0, 2 * Math.PI, false); // x, y, radius, start angle, end angle
    Game.context.fillStyle = grd; //Game.hex2rgba('#d4d4d4', 10);
    Game.context.fill();
    // drawing moon
    Game.context.drawImage(Game.images['moon'], 0, 30, 265, 150);

    // creating star positions
    for (var i = 0; i < Game.numstars; i++) {
      Game.starpositions.push({
        x: Game.randomInt(250, Game.WIDTH),
        y: Game.randomInt(10, Game.sky_level)
      });
    }
  },

  clear: function() {
    // clearing content
    Game.c.clearRect(0, Game.sky_level, Game.WIDTH, Game.ground_level - Game.sky_level);
  }
};

window.onload = function() {
  if (window.focus) window.focus();
  swal({title:"The Ghost Writer Game", text:"Type as fast as you can to kill the ghosts!<br> Use only keys from a to z. <br>Beware! Not every key will shoot.. they randomly change. <br><h3>NOW MOVE!</h3>", html: true, timer: 4500, showConfirmButton: true});
  // creating forbidden key
  Game.createForbidden();
  Game.init();

  // every few seconds, we'll replace forbidden c
  Game.forbiddenTimer = (Math.random() * 40) + 20;
  Game.forbiddenInterval = setInterval(function() {
    // creating forbidden keys
    Game.createForbidden();
    // replacing old forbidden timer
    Game.forbiddenTimer = (Math.random() * 40) + 20;
  }, Game.forbiddenTimer);

  // creating a ghost every few seconds
  Game.ghostTimer = 10000;
  Game.ghostInterval = setInterval(function() {
    Game.createGhost();
  }, Game.ghostTimer);

  // decreasing ghost timer every 10 seconds
  Game.speedTimer = 10000;
  Game.speedInterval = setInterval(function() {
    Game.ghostTimer -= 100;
    if (Game.ghostTimer == 0) clearInterval(Game.ghostInterval);
  }, Game.speedTimer);

  // ui interval
  Game.uiTimer = 500;
  Game.uiInterval = setInterval(function() {
    // updating ui
    document.getElementById('points').innerHTML = "" + Game.points;
    document.getElementById('speed').innerHTML = "" + Game.reaction + "s";
    document.getElementById('bullets').innerHTML = "" + Game.bullet_count;
  }, Game.uiTimer);

  Game.lastreaction = new Date().getTime();
  
  // creating keypress combos
  Game.listener = new window.keypress.Listener();
  Game.combo = [];
  for (var i in Game.keys) {
    Game.combo.push({
      keys: Game.keys[i],
      on_keyup: function() {
        onkeyup({key: Game.keys[i]});
      }
    })
  }
  // registering combo
  Game.listener.register_many(Game.combo);
};

function onkeyup(event) {
  if (Game.over) return false;

  var now = new Date().getTime(); // timestamp
  var diff = now - Game.lastreaction;
  if (diff / 1000 < Game.reaction) {
    Game.reaction = diff / 1000;
  }
  Game.lastreaction = now;

  // a seconda di quello che premiamo, verifichiamo se sparare o se creare un nuovo fantasma
  if ((Game.forbidden.indexOf(event.key.toLowerCase()) == -1) && (Game.keys.indexOf(event.key) != -1)) {
    // we pushed a valid button
    // firing a bullet
    if (Game.isreloading) return;

    Game.fireBullet();
    Game.bullet_count++;

    console.log(Game.bullet_count);

    if (Game.bullet_count % 50 == 0) {
      // we're reloading cannon
      document.getElementById("reloading").innerHTML = "reloading..";
      Game.isreloading = true;
      setTimeout(function() {
        Game.isreloading = false;
        document.getElementById("reloading").innerHTML = "";
      }, 2000);
    }
  } else {
    // nope, creating ghost
    Game.createGhost();
  }
};

// http://paulirish.com/2011/requestanimationframe-for-smart-animating/
// http://my.opera.com/emoller/blog/2011/12/20/requestanimationframe-for-smart-er-animating

// requestAnimationFrame polyfill by Erik Möller. fixes from Paul Irish and Tino Zijdel

// MIT license

(function() {
  var lastTime = 0;
  var vendors = ['ms', 'moz', 'webkit', 'o'];
  for (var x = 0; x < vendors.length && !window.requestAnimationFrame; ++x) {
    Game.requestAnimationFrame = window[vendors[x] + 'RequestAnimationFrame'];
    Game.cancelAnimationFrame = window[vendors[x] + 'CancelAnimationFrame'] || window[vendors[x] + 'CancelRequestAnimationFrame'];
  }

  if (!Game.requestAnimationFrame)
    Game.requestAnimationFrame = function(callback, element) {
      var currTime = new Date().getTime();
      var timeToCall = Math.max(0, 16 - (currTime - lastTime));
      var id = window.setTimeout(function() {
          callback(currTime + timeToCall);
        },
        timeToCall);
      lastTime = currTime + timeToCall;
      return id;
    };

  if (!Game.cancelAnimationFrame)
    Game.cancelAnimationFrame = function(id) {
      clearTimeout(id);
    };
}());